SET NOCOUNT ON;
SET XACT_ABORT ON;
IF DB_NAME()<>N'DemoDatabase' THROW 51900,'Operations seed validator target must be DemoDatabase',1;
IF NOT EXISTS(SELECT 1 FROM dbo.SchemaMigrationHistory WHERE migration_id='065_warehouse_operations_redesign') THROW 51901,'Migration 065 is required',1;
DECLARE @ExpectedAdmins int=2,@ExpectedStaff int=6,@ExpectedShippers int=4,@ExpectedCustomers int=20;
DECLARE @ExpectedProducts int=40,@ExpectedVariants int=100,@ExpectedIngredients int=40,@ExpectedRecipeLines int=200,@ExpectedOrders int=180;
DECLARE @ExpectedReceipts int=4,@ExpectedStockCounts int=4,@ExpectedExpenses int=8,@ExpectedAssets int=5,@ExpectedBanners int=4,@ExpectedActivityLogs int=12;
DECLARE @StartDate date=DATEADD(day,-29,CAST(SYSDATETIME() AS date));
DECLARE @People TABLE(role_name varchar(20),email varchar(255),phone varchar(20));
INSERT @People VALUES('ADMIN','nguyen.an@gmail.local','0908101001'),('ADMIN','tran.minh.chau@gmail.local','0908101002'),('STAFF','le.thu.ha@gmail.local','0908101003'),('STAFF','pham.gia.huy@gmail.local','0908101004'),('STAFF','vo.ngoc.lan@gmail.local','0908101005'),('STAFF','bui.quoc.bao@gmail.local','0908101006'),('STAFF','do.thanh.tam@gmail.local','0908101007'),('STAFF','hoang.my.linh@gmail.local','0908101008'),('SHIPPER','nguyen.duc.long@gmail.local','0908101009'),('SHIPPER','tran.huu.phuc@gmail.local','0908101010'),('SHIPPER','le.tuan.kiet@gmail.local','0908101011'),('SHIPPER','pham.manh.cuong@gmail.local','0908101012'),('USER','nguyen.thao.vy@gmail.local','0908101013'),('USER','tran.quang.huy@gmail.local','0908101014'),('USER','le.hoai.thuong@gmail.local','0908101015'),('USER','pham.ngoc.anh@gmail.local','0908101016'),('USER','vo.minh.khang@gmail.local','0908101017'),('USER','bui.khanh.ly@gmail.local','0908101018'),('USER','do.gia.bao@gmail.local','0908101019'),('USER','hoang.thu.trang@gmail.local','0908101020'),('USER','ngo.tuan.anh@gmail.local','0908101021'),('USER','dang.bich.ngoc@gmail.local','0908101022'),('USER','duong.thanh.nam@gmail.local','0908101023'),('USER','ly.hai.yen@gmail.local','0908101024'),('USER','truong.minh.thu@gmail.local','0908101025'),('USER','dinh.quoc.viet@gmail.local','0908101026'),('USER','mai.thanh.ha@gmail.local','0908101027'),('USER','cao.phuong.linh@gmail.local','0908101028'),('USER','lam.hoang.son@gmail.local','0908101029'),('USER','phan.ngoc.mai@gmail.local','0908101030'),('USER','vu.thanh.dat@gmail.local','0908101031'),('USER','ta.kim.ngan@gmail.local','0908101032');
IF (SELECT COUNT(*) FROM dbo.Users u JOIN @People p ON p.email=u.email AND p.phone=u.phone WHERE p.role_name='ADMIN' AND u.role_name=p.role_name)<>@ExpectedAdmins THROW 51902,'Expected exactly 2 owned ADMIN users',1;
IF (SELECT COUNT(*) FROM dbo.Users u JOIN @People p ON p.email=u.email AND p.phone=u.phone WHERE p.role_name='STAFF' AND u.role_name=p.role_name)<>@ExpectedStaff THROW 51903,'Expected exactly 6 owned STAFF users',1;
IF (SELECT COUNT(*) FROM dbo.Users u JOIN @People p ON p.email=u.email AND p.phone=u.phone WHERE p.role_name='SHIPPER' AND u.role_name=p.role_name)<>@ExpectedShippers THROW 51904,'Expected exactly 4 owned SHIPPER users',1;
IF (SELECT COUNT(*) FROM dbo.Users u JOIN @People p ON p.email=u.email AND p.phone=u.phone WHERE p.role_name='USER' AND u.role_name=p.role_name)<>@ExpectedCustomers THROW 51905,'Expected exactly 20 owned customers',1;
IF EXISTS(SELECT email FROM @People GROUP BY email HAVING COUNT(*)<>1) OR EXISTS(SELECT phone FROM @People GROUP BY phone HAVING COUNT(*)<>1) THROW 51906,'Owned user tuple duplicate or drift',1;
IF (SELECT COUNT(*) FROM dbo.Address a JOIN dbo.Users u ON u.user_id=a.user_id JOIN @People p ON p.email=u.email AND p.phone=u.phone WHERE p.role_name='USER' AND a.is_default=1)<>@ExpectedCustomers THROW 51907,'Expected customer address coverage',1;
IF (SELECT COUNT(*) FROM dbo.Category WHERE description LIKE N'FG-OPS-CATEGORY-%')<>7 THROW 51908,'Expected seven natural menu categories',1;
IF EXISTS(SELECT 1 FROM (VALUES(1,6),(2,6),(3,6),(4,6),(5,6),(6,5),(7,5)) expected(n,quantity) LEFT JOIN(SELECT TRY_CONVERT(int,RIGHT(c.description,2)) n,COUNT(DISTINCT p.product_id) quantity FROM dbo.Category c JOIN dbo.Product p ON p.category_id=c.category_id WHERE c.description LIKE N'FG-OPS-CATEGORY-%' GROUP BY c.description) actual ON actual.n=expected.n WHERE ISNULL(actual.quantity,0)<>expected.quantity) THROW 51909,'Expected category distribution 6-6-6-6-6-5-5',1;
IF (SELECT COUNT(DISTINCT product_id) FROM dbo.ProductVariant WHERE sku LIKE 'FG-OPS-SKU-%')<>@ExpectedProducts THROW 51910,'Expected 40 products',1;
IF (SELECT COUNT(*) FROM dbo.ProductVariant WHERE sku LIKE 'FG-OPS-SKU-%')<>@ExpectedVariants THROW 51911,'Expected 100 variants',1;
IF EXISTS(SELECT product_id FROM dbo.ProductVariant WHERE sku LIKE 'FG-OPS-SKU-%' GROUP BY product_id HAVING COUNT(*) NOT BETWEEN 2 AND 3 OR SUM(CONVERT(int,is_default))<>1) THROW 51912,'Expected two or three variants per product',1;
IF (SELECT COUNT(*) FROM dbo.InventoryItem WHERE inventory_code LIKE 'FG-OPS-ING-%')<>@ExpectedIngredients THROW 51913,'Expected 40 ingredients',1;
IF (SELECT COUNT(*) FROM dbo.RecipeItem ri JOIN dbo.Recipe r ON r.recipe_id=ri.recipe_id JOIN dbo.ProductVariant v ON v.variant_id=r.variant_id WHERE v.sku LIKE 'FG-OPS-SKU-%')<>@ExpectedRecipeLines THROW 51914,'Expected recipe coverage',1;
IF EXISTS(SELECT v.product_id,ri.inventory_item_id FROM dbo.ProductVariant v JOIN dbo.Recipe r ON r.variant_id=v.variant_id JOIN dbo.RecipeItem ri ON ri.recipe_id=r.recipe_id WHERE v.sku LIKE 'FG-OPS-SKU-%' GROUP BY v.product_id,ri.inventory_item_id HAVING MIN(ri.quantity)>=MAX(ri.quantity)) THROW 51915,'Expected variant recipe scaling',1;
IF NOT EXISTS(SELECT 1 FROM dbo.ProductModifierGroup g JOIN dbo.ProductModifierOption o ON o.modifier_group_id=g.modifier_group_id JOIN dbo.ProductVariant v ON v.product_id=g.product_id WHERE v.sku LIKE 'FG-OPS-SKU-%') THROW 51916,'Expected modifier coverage',1;
IF (SELECT COUNT(*) FROM dbo.Orders WHERE order_code LIKE 'FG-OPS-ORD-%')<>@ExpectedOrders THROW 51917,'Expected 180 orders',1;
IF (SELECT COUNT(DISTINCT CAST(created_at AS date)) FROM dbo.Orders WHERE order_code LIKE 'FG-OPS-ORD-%')<>30 THROW 51918,'Expected 30 inclusive operating dates',1;
IF EXISTS(SELECT 1 FROM dbo.Orders o OUTER APPLY(SELECT SUM(total_price) item_total FROM dbo.OrderItem WHERE order_id=o.order_id)x WHERE o.order_code LIKE 'FG-OPS-ORD-%' AND (x.item_total<>o.total_amount OR o.final_amount<>o.total_amount+o.shipping_fee+o.service_fee-o.discount_amount)) THROW 51919,'Order arithmetic invalid',1;
IF EXISTS(SELECT 1 FROM dbo.Orders WHERE order_code LIKE 'FG-OPS-ORD-%' AND ((order_status='DELIVERED' AND delivered_at IS NULL) OR (order_status='CANCELLED' AND cancelled_at IS NULL) OR (payment_status='PAID' AND paid_at IS NULL))) THROW 51920,'Order timeline invalid',1;
IF EXISTS(SELECT 1 FROM dbo.Review r JOIN dbo.Orders o ON o.order_id=r.order_id WHERE o.order_status<>'DELIVERED') THROW 51921,'Review eligibility invalid',1;
IF NOT EXISTS(SELECT 1 FROM dbo.Cart c JOIN dbo.CartItem ci ON ci.cart_id=c.cart_id JOIN dbo.Users u ON u.user_id=c.user_id JOIN @People p ON p.email=u.email AND p.phone=u.phone) OR NOT EXISTS(SELECT 1 FROM dbo.CouponRedemption cr JOIN dbo.Users u ON u.user_id=cr.user_id JOIN @People p ON p.email=u.email AND p.phone=u.phone) OR NOT EXISTS(SELECT 1 FROM dbo.LoyaltyTransaction lt JOIN dbo.Users u ON u.user_id=lt.user_id JOIN @People p ON p.email=u.email AND p.phone=u.phone) OR NOT EXISTS(SELECT 1 FROM dbo.Users u JOIN @People p ON p.email=u.email AND p.phone=u.phone WHERE u.favorite_ids_json<>N'[]') THROW 51922,'Expected customer engagement coverage',1;
IF (SELECT COUNT(*) FROM dbo.WorkShift w JOIN dbo.Users u ON u.user_id=w.user_id JOIN @People p ON p.email=u.email AND p.phone=u.phone WHERE p.role_name IN('STAFF','SHIPPER'))<>300 THROW 51923,'Expected workforce schedule coverage',1;
IF (SELECT COUNT(*) FROM dbo.StaffPayRate r JOIN dbo.Users u ON u.user_id=r.user_id JOIN @People p ON p.email=u.email AND p.phone=u.phone WHERE p.role_name IN('STAFF','SHIPPER'))<>10 THROW 51924,'Expected pay rates',1;
IF (SELECT COUNT(DISTINCT c.status) FROM dbo.CodSettlement c JOIN dbo.Users u ON u.user_id=c.shipper_id JOIN @People p ON p.email=u.email AND p.phone=u.phone)<>4 THROW 51925,'Expected COD reconciliation states',1;
IF (SELECT COUNT(*) FROM dbo.GoodsReceipt WHERE invoice_number LIKE N'FG-OPS-REC-%')<>@ExpectedReceipts OR (SELECT COUNT(*) FROM dbo.StockCount sc JOIN dbo.Users u ON u.user_id=sc.created_by JOIN @People p ON p.email=u.email AND p.phone=u.phone)<>@ExpectedStockCounts THROW 51926,'Expected receipts and stock counts',1;
IF EXISTS(SELECT 1 FROM dbo.InventoryTransaction t JOIN dbo.InventoryItem i ON i.inventory_item_id=t.inventory_item_id WHERE i.inventory_code LIKE 'FG-OPS-ING-%' AND (t.quantity_after<>t.quantity_before+t.quantity OR t.total_cost<0)) THROW 51927,'Inventory transaction math invalid',1;
IF (SELECT COUNT(*) FROM dbo.OperatingExpense WHERE (expense_date=@StartDate AND category='RENT' AND description=N'Tiền thuê mặt bằng tháng này' AND amount=28000000) OR (expense_date=DATEADD(day,4,@StartDate) AND category='UTILITIES' AND description=N'Tiền điện khu bếp và sảnh' AND amount=6850000) OR (expense_date=DATEADD(day,8,@StartDate) AND category='MARKETING' AND description=N'Chi phí quảng bá thực đơn mới' AND amount=4200000) OR (expense_date=DATEADD(day,12,@StartDate) AND category='MAINTENANCE' AND description=N'Bảo dưỡng hệ thống hút khói' AND amount=3100000) OR (expense_date=DATEADD(day,16,@StartDate) AND category='OTHER' AND description=N'Vật tư vệ sinh cửa hàng' AND amount=1850000) OR (expense_date=DATEADD(day,20,@StartDate) AND category='UTILITIES' AND description=N'Tiền nước và internet cửa hàng' AND amount=2750000) OR (expense_date=DATEADD(day,24,@StartDate) AND category='MARKETING' AND description=N'In tờ rơi khuyến mãi cuối tuần' AND amount=1600000) OR (expense_date=DATEADD(day,28,@StartDate) AND category='MAINTENANCE' AND description=N'Bảo trì tủ đông nguyên liệu' AND amount=2400000))<>@ExpectedExpenses THROW 51928,'OperatingExpense exact tuple duplicate or drift',1;
IF (SELECT COUNT(*) FROM dbo.FixedAsset WHERE (asset_name=N'Lò nướng đối lưu Unox' AND acquisition_cost=68000000 AND salvage_value=6800000 AND depreciation_start_date=DATEADD(month,-18,@StartDate) AND useful_life_months=60) OR (asset_name=N'Tủ đông inox bốn cánh' AND acquisition_cost=42000000 AND salvage_value=4200000 AND depreciation_start_date=DATEADD(month,-14,@StartDate) AND useful_life_months=60) OR (asset_name=N'Máy pha cà phê hai vòi' AND acquisition_cost=36000000 AND salvage_value=3600000 AND depreciation_start_date=DATEADD(month,-10,@StartDate) AND useful_life_months=48) OR (asset_name=N'Hệ thống máy bán hàng' AND acquisition_cost=24000000 AND salvage_value=2400000 AND depreciation_start_date=DATEADD(month,-8,@StartDate) AND useful_life_months=36) OR (asset_name=N'Xe máy giao hàng Honda Wave' AND acquisition_cost=22000000 AND salvage_value=5000000 AND depreciation_start_date=DATEADD(month,-6,@StartDate) AND useful_life_months=48))<>@ExpectedAssets THROW 51929,'FixedAsset exact tuple duplicate or drift',1;
IF (SELECT COUNT(*) FROM dbo.Banner WHERE link LIKE '/menu?campaign=fg-ops-%')<>@ExpectedBanners OR (SELECT COUNT(*) FROM dbo.ActivityLog WHERE action_type='FG_OPS_ORDER_REVIEW' AND target_id LIKE N'FG-OPS-ORD-%')<>@ExpectedActivityLogs THROW 51930,'Expected finance, merchandising and audit coverage',1;
IF EXISTS(SELECT 1 FROM dbo.Product p JOIN dbo.ProductVariant v ON v.product_id=p.product_id WHERE v.sku LIKE 'FG-OPS-SKU-%' AND (LOWER(p.name) LIKE N'%demo%' OR LOWER(p.name) LIKE N'%mẫu%' OR LOWER(p.name) LIKE N'%trình diễn%')) THROW 51931,'Forbidden presentation wording in visible fields',1;
SELECT p.role_name,COUNT(*) owned_users FROM dbo.Users u JOIN @People p ON p.email=u.email AND p.phone=u.phone GROUP BY p.role_name ORDER BY p.role_name;
SELECT COUNT(DISTINCT product_id) product_count,COUNT(*) variant_count FROM dbo.ProductVariant WHERE sku LIKE 'FG-OPS-SKU-%';
SELECT COUNT(*) order_count,COUNT(DISTINCT CAST(created_at AS date)) operating_days,SUM(CASE WHEN order_status='DELIVERED' THEN final_amount ELSE 0 END) delivered_revenue FROM dbo.Orders WHERE order_code LIKE 'FG-OPS-ORD-%';
SELECT (SELECT COUNT(*) FROM dbo.GoodsReceipt WHERE invoice_number LIKE N'FG-OPS-REC-%') receipts,(SELECT COUNT(*) FROM dbo.OperatingExpense WHERE created_by IN(SELECT u.user_id FROM dbo.Users u JOIN @People p ON p.email=u.email AND p.phone=u.phone)) expenses,(SELECT COUNT(*) FROM dbo.FixedAsset WHERE created_by IN(SELECT u.user_id FROM dbo.Users u JOIN @People p ON p.email=u.email AND p.phone=u.phone)) assets;
PRINT 'Presentation demo seed validation passed';
